/// The theme for an appearance.
pub const fn theme(dark: bool) -> &'static Theme {
    if dark {
        &DARK
    } else {
        &LIGHT
    }
}

/// What is in this file on the supervisor's say and not yet the user's.
/// Each is one value in the data; ruling on it is one edit there.
pub const TENTATIVE: &[&str] = &[
    "window_tab.working_glyph_shown",
    "side.fix_line_height",
    "side.ask_max_lines",
    "side.ask_max_steps",
    "stack_tab.inset",
    "stack_tab.min_width",
    "elsewhere.veil",
    "selection.spring_damping",
    "selection.glass_at_rest",
    "selection.refraction_shown",
    "selection.seen_after",
    "text_on.problem_text",
];
